#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; long long m; cin >> n >> m;
    unordered_map<long long,int> cnt; cnt.reserve(n * 2 + 1);
    for (int i = 0; i < n; i++){ long long x; cin >> x; cnt[x]++; }
    vector<int> f; for (auto &p : cnt) f.push_back(p.second);
    sort(f.begin(), f.end());
    int left = f.size();
    for (int x : f){ if (m < x) break; m -= x; left--; }
    cout << left << "\n";
}

